	t.Helper()
	home := t.TempDir()
	if err := hooktest.Write(filepath.Join(home, "hooks.json"), hooktest.Entry{
		Event:    hooks.EventPreToolUse,
		Matcher:  "run_command",
		Handlers: []hooks.Handler{hooktest.Handler("rewrite-ask", hookCommand)},
	}); err != nil {
		t.Fatal(err)
	}
